import React, { useState, useEffect } from 'react';
import { Search, Plus, Menu, Heart, MessageCircle, Share, Bookmark, ChevronLeft, ChevronRight } from 'lucide-react';
import SwipeableContainer from './SwipeableContainer';
import './MainFeed.css';

const sampleData = {
  posts: [
    {
      id: 1,
      author: '山田花子',
      username: '@yamada_hanako',
      isAnonymous: false,
      time: '2時間前',
      content: '今日の授業めっちゃ面白かった！AI について学んだよ 🤖✨\n\n#東京大学 #AI #授業',
      likes: 24,
      comments: 8,
      shares: 3,
      isLiked: false,
      isBookmarked: false,
      category: '学業',
      board: '自由掲示板',
      images: ['https://via.placeholder.com/300x200/4facfe/white?text=AI+Class'],
      circles: ['AI研究会', 'プログラミング部'],
      price: null
    },
    {
      id: 2,
      author: '匿名ユーザー',
      username: null,
      isAnonymous: true,
      time: '4時間前',
      content: '誰か一緒にカフェで勉強しませんか？☕📚\n場所：渋谷のスタバ\n時間：明日14:00〜',
      likes: 12,
      comments: 15,
      shares: 2,
      isLiked: true,
      isBookmarked: true,
      category: '交流',
      board: '自由掲示板',
      images: [],
      circles: [],
      price: null
    },
    {
      id: 3,
      author: '佐藤太郎',
      username: '@sato_taro',
      isAnonymous: false,
      time: '6時間前',
      content: 'MacBook Pro 売ります！\n2021年モデル、M1チップ\n使用期間：1年\n付属品完備 💻',
      likes: 45,
      comments: 23,
      shares: 8,
      isLiked: false,
      isBookmarked: false,
      category: '売買',
      board: 'フリーマーケット',
      images: ['https://via.placeholder.com/300x200/333/white?text=MacBook+Pro'],
      circles: [],
      price: '¥180,000'
    }
  ]
};

const MainFeed = ({ user, setUser }) => {
  const [activeTab, setActiveTab] = useState('recommended');
  const [showSidebar, setShowSidebar] = useState(false);
  const [showSearchBar, setShowSearchBar] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [posts, setPosts] = useState(sampleData.posts);
  const [newPost, setNewPost] = useState({ content: '', images: [], isAnonymous: false });
  const [headerVisible, setHeaderVisible] = useState(true);
  const [lastScrollY, setLastScrollY] = useState(0);
  const [touchStart, setTouchStart] = useState(null);
  const [touchEnd, setTouchEnd] = useState(null);

  useEffect(() => {
    const samplePosts = [
      {
        id: 1,
        author: '山田花子',
        username: '@yamada_hanako',
        isAnonymous: false,
        time: '2時間前',
        content: '今日の授業めっちゃ面白かった！AI について学んだよ 🤖✨\n\n#東京大学 #AI #授業',
        likes: 24,
        comments: 8,
        shares: 3,
        isLiked: false,
        isBookmarked: false,
        category: '学業',
        board: '自由掲示板',
        images: ['https://via.placeholder.com/300x200/4facfe/white?text=AI+Class'],
        circles: ['AI研究会', 'プログラミング部'],
        price: null
      },
      {
        id: 2,
        author: '匿名ユーザー',
        username: null,
        isAnonymous: true,
        time: '4時間前',
        content: '誰か一緒にカフェで勉強しませんか？☕📚\n場所：渋谷のスタバ\n時間：明日14:00〜',
        likes: 12,
        comments: 15,
        shares: 2,
        isLiked: true,
        isBookmarked: true,
        category: '交流',
        board: '自由掲示板',
        images: [],
        circles: [],
        price: null
      },
      {
        id: 3,
        author: '佐藤太郎',
        username: '@sato_taro',
        isAnonymous: false,
        time: '6時間前',
        content: 'MacBook Pro 売ります！\n2021年モデル、M1チップ\n使用期間：1年\n付属品完備 💻',
        likes: 45,
        comments: 23,
        shares: 8,
        isLiked: false,
        isBookmarked: false,
        category: '売買',
        board: 'フリーマーケット',
        images: ['https://via.placeholder.com/300x200/333/white?text=MacBook+Pro'],
        circles: [],
        price: '¥180,000'
      }
    ];
    setPosts(samplePosts);
  }, []);

  const handlePostAction = (postId, action) => {
    setPosts(posts.map(post => {
      if (post.id === postId) {
        switch (action) {
          case 'like':
            return { ...post, likes: post.isLiked ? post.likes - 1 : post.likes + 1, isLiked: !post.isLiked };
          case 'bookmark':
            return { ...post, isBookmarked: !post.isBookmarked };
          default:
            return post;
        }
      }
      return post;
    }));
  };

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;

      if (currentScrollY > lastScrollY && currentScrollY > 100) {
        setHeaderVisible(false);
      } else {
        setHeaderVisible(true);
      }

      setLastScrollY(currentScrollY);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lastScrollY]);

  useEffect(() => {
    const handleTouchStart = (e) => {
      if (e.touches[0].clientX < 50) {
        setTouchStart(e.touches[0].clientX);
      }
    };

    const handleTouchMove = (e) => {
      if (touchStart !== null) {
        setTouchEnd(e.touches[0].clientX);
      }
    };

    const handleTouchEnd = () => {
      if (touchStart !== null && touchEnd !== null) {
        const distance = touchEnd - touchStart;
        if (distance > 100) {
          setShowSidebar(true);
        }
      }
      setTouchStart(null);
      setTouchEnd(null);
    };

    document.addEventListener('touchstart', handleTouchStart, { passive: true });
    document.addEventListener('touchmove', handleTouchMove, { passive: true });
    document.addEventListener('touchend', handleTouchEnd);

    return () => {
      document.removeEventListener('touchstart', handleTouchStart);
      document.removeEventListener('touchmove', handleTouchMove);
      document.removeEventListener('touchend', handleTouchEnd);
    };
  }, [touchStart, touchEnd]);

  const ImageSlider = ({ images }) => {
    const [currentImage, setCurrentImage] = useState(0);

    if (!images || images.length === 0) return null;

    return (
      <div className="image-slider">
        <img src={images[currentImage]} alt="Post content" />
        {images.length > 1 && (
          <>
            <button 
              className="slider-btn prev"
              onClick={() => setCurrentImage(prev => prev > 0 ? prev - 1 : images.length - 1)}
            >
              <ChevronLeft size={20} />
            </button>
            <button 
              className="slider-btn next"
              onClick={() => setCurrentImage(prev => prev < images.length - 1 ? prev + 1 : 0)}
            >
              <ChevronRight size={20} />
            </button>
            <div className="slider-dots">
              {images.map((_, index) => (
                <div 
                  key={index}
                  className={`dot ${index === currentImage ? 'active' : ''}`}
                  onClick={() => setCurrentImage(index)}
                />
              ))}
            </div>
          </>
        )}
      </div>
    );
  };

  const PostCard = ({ post }) => (
    <div className="post-card card japanese-card fade-in">
      <div className="post-header">
        <div className="author-info">
          <div className="avatar">
            {post.isAnonymous ? '🎭' : '👤'}
          </div>
          <div className="author-details">
            <div className="author-name">
              {post.isAnonymous ? '匿名ユーザー' : post.author}
            </div>
            {!post.isAnonymous && (
              <div className="username">{post.username}</div>
            )}
            <div className="post-meta">
              <span className="time">{post.time}</span>
              <span className="category badge badge-primary">{post.category}</span>
              {post.price && <span className="price badge badge-secondary">{post.price}</span>}
            </div>
          </div>
        </div>
      </div>

      <div className="post-content">
        <p>{post.content}</p>
        <ImageSlider images={post.images} />

        {post.circles.length > 0 && (
          <div className="circles">
            {post.circles.map((circle, index) => (
              <span key={index} className="circle-tag badge badge-success">
                🎯 {circle}
              </span>
            ))}
          </div>
        )}
      </div>

      <div className="post-actions">
        <button 
          className={`action-btn ${post.isLiked ? 'liked' : ''}`}
          onClick={() => handlePostAction(post.id, 'like')}
        >
          <Heart size={18} fill={post.isLiked ? '#ff6b6b' : 'none'} />
          <span>{post.likes}</span>
        </button>

        <button className="action-btn">
          <MessageCircle size={18} />
          <span>{post.comments}</span>
        </button>

        <button className="action-btn">
          <Share size={18} />
          <span>{post.shares}</span>
        </button>

        <button 
          className={`action-btn ${post.isBookmarked ? 'saved' : ''}`}
          onClick={() => handlePostAction(post.id, 'bookmark')}
        >
          <Bookmark size={18} fill={post.isBookmarked ? '#4facfe' : 'none'} />
        </button>
      </div>
    </div>
  );

  const Sidebar = () => (
    <div className={`sidebar-overlay ${showSidebar ? 'active' : ''}`} onClick={() => setShowSidebar(false)}>
      <div className={`sidebar ${showSidebar ? 'active' : ''}`} onClick={e => e.stopPropagation()}>
        <div className="sidebar-header">
          <h3>メニュー</h3>
          <button className="close-btn" onClick={() => setShowSidebar(false)}>×</button>
        </div>

        <div className="sidebar-content">
          <div className="user-profile">
            <div className="avatar large">👤</div>
            <div className="user-info">
              <div className="name">{user.name}</div>
              <div className="department">{user.department} {user.year}年</div>
            </div>
          </div>

          <div className="menu-section">
            <h4>🔥 トレンド</h4>
            <div className="trending-item">#春休み計画</div>
            <div className="trending-item">#新学期準備</div>
            <div className="trending-item">#サークル募集</div>
          </div>

          <div className="menu-section">
            <h4>🎯 人気サークル</h4>
            <div className="circle-item">
              <span>🏀 バスケ部</span>
              <span className="member-count">234人</span>
            </div>
            <div className="circle-item">
              <span>🎵 軽音楽部</span>
              <span className="member-count">189人</span>
            </div>
            <div className="circle-item">
              <span>🤖 AI研究会</span>
              <span className="member-count">156人</span>
            </div>
          </div>

          <div className="menu-section">
            <h4>⚙️ 設定</h4>
            <div className="setting-item">
              <label>
                <input 
                  type="checkbox" 
                  checked={user.isAnonymous}
                  onChange={(e) => setUser({...user, isAnonymous: e.target.checked})}
                />
                匿名モード
              </label>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const CreatePostModal = () => (
    showCreateModal && (
      <div className="modal-overlay" onClick={() => setShowCreateModal(false)}>
        <div className="modal-content" onClick={e => e.stopPropagation()}>
          <div className="modal-header">
            <h3>新しい投稿</h3>
            <button className="close-btn" onClick={() => setShowCreateModal(false)}>×</button>
          </div>
          <div className="modal-body">
            <div className="form-group">
              <textarea 
                className="form-textarea" 
                placeholder="今何してる？🤔"
                rows="4"
              />
            </div>
            <div className="form-group">
              <select className="form-input">
                <option>カテゴリを選択</option>
                <option>学業</option>
                <option>交流</option>
                <option>売買</option>
                <option>その他</option>
              </select>
            </div>
            <button className="btn btn-primary">投稿する</button>
          </div>
        </div>
      </div>
    )
  );

  return (
    <div className="main-feed">
      <div className={`feed-header ${headerVisible ? 'visible' : 'hidden'}`}>
        <button className="menu-btn" onClick={() => setShowSidebar(true)}>
          <Menu size={24} />
        </button>
        <h1 className={`feed-title ${headerVisible ? 'visible' : 'hidden'}`}>홈</h1>
        <button className="search-btn" onClick={() => setShowSearchBar(!showSearchBar)}>
          <Search size={24} />
        </button>
      </div>

      <div className={`search-bar ${showSearchBar ? 'show' : ''}`}>
        <Search size={16} />
        <input
          type="text"
          placeholder="검색어를 입력하세요..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      <div className="tab-container">
        <button 
          className={`tab-button ${activeTab === 'recommended' ? 'active' : ''}`}
          onClick={() => setActiveTab('recommended')}
        >
          おすすめ
        </button>
        <button 
          className={`tab-button ${activeTab === 'following' ? 'active' : ''}`}
          onClick={() => setActiveTab('following')}
        >
          フォロー中
        </button>
      </div>

      <div className="slide-content">
        <div className="slide-item">
          <h4>💬 人気コメント</h4>
          <p>"今度のテスト頑張ろう！"</p>
        </div>
      </div>

      <div className="posts-container">
        {posts.map(post => (
          <SwipeableContainer
            key={post.id}
            onSwipeLeft={() => handleSave(post.id)}
            onSwipeRight={() => handleLike(post.id)}
          >
            <PostCard post={post} />
          </SwipeableContainer>
        ))}
      </div>

      <button className="fab" onClick={() => setShowCreatePost(true)}>
        <Plus size={24} />
      </button>

      <Sidebar />
      <CreatePostModal />
    </div>
  );
};

export default MainFeed;
